; sixteen.asm -- chapter 8: two pairs swapped, copied and stored
; generated by gen08.py
        INCLUDE "msx.inc"
        OUTPUT "sixteen.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
store   EQU RAM_START               ; two bytes of RAM
; There is no LD HL,DE. EX DE,HL swaps the two pairs; two LDs copy one into
; the other; LD (nn),HL stores low byte first.
init:   di
        ld sp, SYS_AREA
        ld hl, $1234
        ld de, $5678
        ex de, hl               ; HL = $5678, DE = $1234
p1:     ld h, d
        ld l, e                 ; HL = DE = $1234: a copy
p2:     ld (store), hl          ; $34 at store, $12 after it
p3:     jr p3
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
